/// Test double for [DmVerifyWorker] that runs the real verification inline (no
/// isolate), records the kinds it verified, and tracks teardown — so drain
/// tests assert the verify worker was used and closed without spawning a real
/// isolate. Behaviour-equivalent to the inline main-isolate check, so it does
/// not change any existing drain test's outcome.
class _RecordingVerifyWorker implements DmVerifyWorker {
  final List<int> verifiedKinds = <int>[];
  int closeCount = 0;
  bool closed = false;

  @override
  Future<bool> verifyPart(Event event) async {
    if (closed) {
      throw StateError('DmVerifyWorker has been closed');
    }
    verifiedKinds.add(event.kind);
    return verifyGiftWrapPart(event);
  }

  @override
  void close() {
    closed = true;
    closeCount++;
  }
}

/// Delegating [NostrSigner] whose [getPublicKey] suspends on [gate] — models a
/// remote signer's slow `refreshPublicKey` RPC so tests can run
/// `stopListening()` while a live wrap is parked inside
/// `_handleGiftWrapEvent`, before its `_decryptRumor` call.
class _GatedPubkeySigner implements NostrSigner {
  _GatedPubkeySigner(this._inner, this.gate);

  final NostrSigner _inner;
  final Future<void> gate;

  @override
  Future<String?> getPublicKey() async {
    await gate;
    return _inner.getPublicKey();
  }

  @override
  Future<Event?> signEvent(Event event) => _inner.signEvent(event);

  @override
  Future<Map<dynamic, dynamic>?> getRelays() => _inner.getRelays();

  @override
  Future<String?> encrypt(String pubkey, String plaintext) =>
      _inner.encrypt(pubkey, plaintext);

  @override
  Future<String?> decrypt(String pubkey, String ciphertext) =>
      _inner.decrypt(pubkey, ciphertext);

  @override
  Future<String?> nip44Encrypt(String pubkey, String plaintext) =>
      _inner.nip44Encrypt(pubkey, plaintext);

  @override
  Future<String?> nip44Decrypt(String pubkey, String ciphertext) =>
      _inner.nip44Decrypt(pubkey, ciphertext);

  @override
  void close() => _inner.close();
}

/// Test double for [DmSyncState] that stores values in memory and captures
/// [recordSeen] calls for assertions.
class _FakeDmSyncState implements DmSyncState {
  int? newestOverride;
  int? newestWireOverride;
  int? oldestOverride;
  bool drainCompleteOverride = false;
  int? drainCursorOverride;
  int drainVersionOverride = 0;
  int groupRecoveryVersionOverride = 0;
  final List<String> markedCompletePubkeys = <String>[];
  final List<int> persistedDrainCursors = <int>[];
  final List<String> upgradedPubkeys = <String>[];
  final List<String> repairedPubkeys = <String>[];
  final List<({String pubkey, int createdAt})> recorded =
      <({String pubkey, int createdAt})>[];
  final List<({String pubkey, int createdAt})> recordedWire =
      <({String pubkey, int createdAt})>[];
  bool drainCoveredOwnInboxOverride = false;
  bool completedBeforeOverride = false;
  final List<String> inboxCoveredPubkeys = <String>[];
  final List<String> rearmedForInboxPubkeys = <String>[];
  final List<String> drainPreambleOperations = <String>[];

  @override
  int? newestSyncedAt(String pubkey) => newestOverride;

  @override
  int? newestWireSyncedAt(String pubkey) => newestWireOverride;

  @override
  int? oldestSyncedAt(String pubkey) => oldestOverride;

  @override
  bool historyDrainComplete(String pubkey) => drainCompleteOverride;

  @override
  Future<void> markHistoryDrainComplete(String pubkey) async {
    markedCompletePubkeys.add(pubkey);
    drainCompleteOverride = true;
    completedBeforeOverride = true;
    drainCursorOverride = null;
  }

  @override
  bool historyDrainCompletedBefore(String pubkey) => completedBeforeOverride;

  @override
  Future<void> migrateHistoryDrainCompletion(String pubkey) async {
    drainPreambleOperations.add('migrate-completion');
  }

  @override
  bool drainCoveredOwnInbox(String pubkey) => drainCoveredOwnInboxOverride;

  @override
  Future<void> setDrainCoveredOwnInbox(String pubkey) async {
    inboxCoveredPubkeys.add(pubkey);
    drainCoveredOwnInboxOverride = true;
  }

  @override
  Future<void> rearmDrainForOwnInbox(String pubkey) async {
    rearmedForInboxPubkeys.add(pubkey);
    if (drainCompleteOverride) completedBeforeOverride = true;
    drainCompleteOverride = false;
    drainCursorOverride = DateTime.now().millisecondsSinceEpoch ~/ 1000;
  }

  @override
  int drainVersion(String pubkey) => drainVersionOverride;

  @override
  Future<void> setDrainVersion(String pubkey, int version) async {
    drainVersionOverride = version;
  }

  @override
  int groupRecoveryVersion(String pubkey) => groupRecoveryVersionOverride;

  @override
  Future<void> setGroupRecoveryVersion(String pubkey, int version) async {
    groupRecoveryVersionOverride = version;
  }

  @override
  Future<void> upgradeDrainVersionIfNeeded(String pubkey) async {
    drainPreambleOperations.add('upgrade-version');
    if (drainVersionOverride >= DmSyncState.currentDrainVersion) return;
    upgradedPubkeys.add(pubkey);
    if (drainCompleteOverride) {
      drainCompleteOverride = false;
      drainCursorOverride = DateTime.now().millisecondsSinceEpoch ~/ 1000;
    }
    drainVersionOverride = DmSyncState.currentDrainVersion;
  }

  @override
  Future<void> repairPoisonedBoundaries(String pubkey) async {
    repairedPubkeys.add(pubkey);
    final nowSec = DateTime.now().millisecondsSinceEpoch ~/ 1000;
    var repaired = false;
    final newest = newestOverride;
    if (newest != null && newest > nowSec) {
      newestOverride = nowSec;
      repaired = true;
    }
    final newestWire = newestWireOverride;
    if (newestWire != null && newestWire > nowSec) {
      newestWireOverride = nowSec;
      repaired = true;
    }
    final oldest = oldestOverride;
    if (oldest != null &&
        (oldest < DmSyncState.minPlausibleCreatedAt || oldest > nowSec)) {
      oldestOverride = oldest < DmSyncState.minPlausibleCreatedAt
          ? DmSyncState.minPlausibleCreatedAt
          : nowSec;
      repaired = true;
    }
    if (repaired) {
      drainCompleteOverride = false;
      drainCursorOverride = nowSec;
    }
  }

  @override
  int? historyDrainCursor(String pubkey) => drainCursorOverride;

  @override
  Future<void> setHistoryDrainCursor(String pubkey, int cursor) async {
    drainCursorOverride = cursor;
    persistedDrainCursors.add(cursor);
  }

  final Set<String> dmRelayListPublishedPubkeys = <String>{};

  @override
  bool dmRelayListPublished(String pubkey) =>
      dmRelayListPublishedPubkeys.contains(pubkey);

  @override
  Future<void> markDmRelayListPublished(String pubkey) async {
    dmRelayListPublishedPubkeys.add(pubkey);
  }

  @override
  Future<void> recordWireSeen(String pubkey, {required int createdAt}) async {
    recordedWire.add((pubkey: pubkey, createdAt: createdAt));
    if (newestWireOverride == null || createdAt > newestWireOverride!) {
      newestWireOverride = createdAt;
    }
  }

  @override
  Future<void> recordSeen(String pubkey, {required int createdAt}) async {
    recorded.add((pubkey: pubkey, createdAt: createdAt));
    if (newestOverride == null || createdAt > newestOverride!) {
      newestOverride = createdAt;
    }
    if (oldestOverride == null || createdAt < oldestOverride!) {
      oldestOverride = createdAt;
    }
  }

  @override
  Future<void> clear(String pubkey) async {
    newestOverride = null;
    oldestOverride = null;
    drainCompleteOverride = false;
    drainCursorOverride = null;
    drainVersionOverride = 0;
  }

  @override
  Future<void> clearAll() async {
    newestOverride = null;
    oldestOverride = null;
    drainCompleteOverride = false;
    drainCursorOverride = null;
    drainVersionOverride = 0;
    recorded.clear();
  }
}

/// Records each invocation of a [DmRepositoryErrorReporter] so tests can
/// assert which swallow site emitted.
class _ReporterCall {
  _ReporterCall(this.error, this.stackTrace, this.site);
  final Object error;
  final StackTrace stackTrace;
  final String site;
}

// Valid 64-character hex pubkeys for testing
const _validPubkeyA =
    'a1b2c3d4e5f6789012345678901234567890abcdef1234567890123456789012';
const _validPubkeyB =
    'b2c3d4e5f6789012345678901234567890abcdef1234567890123456789012a1';
const _validPubkeyC =
    'c3d4e5f6789012345678901234567890abcdef1234567890123456789012ab12';
const _validPrivateKey =
    'd4e5f6789012345678901234567890abcdef1234567890123456789012ab12c3';
const _validPubkeyD =
    'd4e5f6789012345678901234567890abcdef1234567890123456789012ab12c3';

const _rumorEventId =
    'e5f6789012345678901234567890abcdef1234567890123456789012ab12c3d4';
const _giftWrapEventId =
    'f6789012345678901234567890abcdef1234567890123456789012ab12c3d4e5';
const _giftWrapEventId2 =
    '06789012345678901234567890abcdef1234567890123456789012ab12c3d4e5';

/// A second message rumor id, for a wrapped deletion naming two targets.
const _secondTargetRumorId =
    '16789012345678901234567890abcdef1234567890123456789012ab12c3d4e5';

void main() {
  group(DmRepository, () {
    late _MockNostrClient mockNostrClient;
    late _MockNIP17MessageService mockMessageService;
    late _MockDirectMessagesDao mockDirectMessagesDao;
    late _MockConversationsDao mockConversationsDao;
    late _MockDmReactionsRepository mockReactionsRepository;
    late List<_ReporterCall> reporterCalls;

    setUpAll(() {
      registerFallbackValue(_FakeEvent());
      registerFallbackValue(_FakeOutgoingDm());
      registerFallbackValue(OutgoingWrapStatus.pending);
      registerFallbackValue(DmDedupCounterpart.nip04Copy);
      // `queryEventsDetailed` takes a `Duration timeout`, so any stub that
      // matches on it needs a fallback (#8212).
      registerFallbackValue(Duration.zero);
    });

    // Everything registered below is a THROW-GUARD, not a decision.
    //
    // The distinction is what #8399 turns on. A *decision* stub stands in for a
    // branch production takes, so inheriting one invisibly can make a class of
    // bug unobservable -- that is how #7324 stayed green here for months. Those
    // have been moved to the groups that depend on them and are declared there
    // by name -- `stubSendPolicyPermitsEveryone`,
    // `stubNoCrossProtocolTwinAvailable` and friends, defined just below
    // `createRepository`.
    //
    // What is left exists only because an unstubbed mocktail member *throws*.
    // No branch reads these values:
    //
    //   * relay counters      -- interpolated into a log line
    //   * runInTransaction    -- runs the callback inline; on 11 persist paths
    //   * markAsRead          -- both production call sites are a bare `await`
    //   * queryEventsDetailed -- send/listener inbox resolution catches its
    //                            throw; RC3 re-declares the answered-empty
    //                            decision explicitly in its own group
    //   * getAllConversations, both backfills, publishSelfApplicationMarker
    //                         -- production CATCHES their throw and logs it, so
    //                            removing them keeps the suite green while
    //                            silently running it against an error branch
    //   * buildRumor/buildGroupRumor -- faithful fakes, not constants; they
    //                            compute real event ids from their arguments
    //
    // Before removing anything here, check the run's logs as well as the test
    // count: grep for `type 'Null' is not a subtype of type '` and compare
    // against the baseline. A green suite is necessary but not sufficient.
    setUp(() {
      mockNostrClient = _MockNostrClient();
      mockMessageService = _MockNIP17MessageService();
      mockDirectMessagesDao = _MockDirectMessagesDao();
      mockConversationsDao = _MockConversationsDao();
      mockReactionsRepository = _MockDmReactionsRepository();
      reporterCalls = <_ReporterCall>[];

      // Stub relay properties used by startListening() log.
      when(() => mockNostrClient.connectedRelayCount).thenReturn(3);
      when(() => mockNostrClient.configuredRelayCount).thenReturn(3);
      when(() => mockNostrClient.isRelayAllowed(any())).thenReturn(true);

      // Default conversation-list read for tests that trigger maintenance.
      when(
        () => mockConversationsDao.getAllConversations(
          ownerPubkey: any(named: 'ownerPubkey'),
        ),
      ).thenAnswer((_) async => []);

      // Catch guard for the broad send/listener kind-10050 lookup surface.
      // Without this, those tests stay green but silently exercise the failed
      // lookup branch. RC3 re-declares the answered-empty decision by name.
      when(
        () => mockNostrClient.queryEventsDetailed(
          any(),
          subscriptionId: any(named: 'subscriptionId'),
          useCache: any(named: 'useCache'),
          tempRelays: any(named: 'tempRelays'),
          requireAllRelaysSettled: any(named: 'requireAllRelaysSettled'),
          timeout: any(named: 'timeout'),
        ),
      ).thenAnswer((_) async => answeredList(const <Event>[]));

      // Stub backfillCurrentUserHasSent for _backfillCurrentUserHasSent().
      when(
        () => mockConversationsDao.backfillCurrentUserHasSent(any()),
      ).thenAnswer((_) async => 0);
      when(
        () => mockConversationsDao.backfillLatestMessagePreviews(
          ownerPubkey: any(named: 'ownerPubkey'),
        ),
      ).thenAnswer((_) async => 0);

      // Global stub for runInTransaction — executes the callback directly.
      // Stub both <void> and <Null> since Dart infers different type args
      // depending on whether the callback returns or is void-typed.
      when(
        () => mockConversationsDao.runInTransaction<void>(any()),
      ).thenAnswer((inv) async {
        final callback = inv.positionalArguments[0] as Future<void> Function();
        await callback();
      });
      when(
        () => mockConversationsDao.runInTransaction<Null>(any()),
      ).thenAnswer((inv) async {
        final callback = inv.positionalArguments[0] as Future<Null> Function();
        await callback();
      });

      // Global stub for markAsRead — every live-send path now marks the
      // conversation read in the same transaction (#5515: sending implies
      // read). Default to a successful flip so send tests don't restub it.
      when(
        () => mockConversationsDao.markAsRead(
          any(),
          ownerPubkey: any(named: 'ownerPubkey'),
        ),
      ).thenAnswer((_) async => true);

      // Global stubs for the #4977 read-state cursor surface so any path that
      // touches the marker reconcile / debounced publish / drain floor has a
      // default. Tests that assert on these restub or verify as needed.
      when(
        () => mockConversationsDao.lastSentTimestampsByConversation(
          any(),
          ownerPubkey: any(named: 'ownerPubkey'),
        ),
      ).thenAnswer((_) async => <String, int>{});
      when(
        () => mockMessageService.publishSelfApplicationMarker(
          content: any(named: 'content'),
          tags: any(named: 'tags'),
          eventKind: any(named: 'eventKind'),
        ),
      ).thenAnswer((_) async => true);

      // Default stub for buildRumor — production sendMessage now calls
      // buildRumor first to enqueue a queue row keyed by the rumor's id
      // before publishing. Returning a real Event so .id is computed
      // deterministically from the rumor fields, matching what the
      // production message service does.
      when(
        () => mockMessageService.buildRumor(
          recipientPubkey: any(named: 'recipientPubkey'),
          content: any(named: 'content'),
          eventKind: any(named: 'eventKind'),
          additionalTags: any(named: 'additionalTags'),
          createdAt: any(named: 'createdAt'),
        ),
      ).thenAnswer((inv) {
        final recipient = inv.namedArguments[#recipientPubkey] as String;
        final content = inv.namedArguments[#content] as String;
        final eventKind =
            (inv.namedArguments[#eventKind] as int?) ??
            EventKind.privateDirectMessage;
        final additionalTags =
            (inv.namedArguments[#additionalTags] as List<List<String>>?) ??
            const <List<String>>[];
        final createdAt = inv.namedArguments[#createdAt] as int?;
        return Event(
          _validPubkeyA,
          eventKind,
          [
            ['p', recipient],
            ...additionalTags,
          ],
          content,
          createdAt: createdAt,
        );
      });

      // Faithful mirror of Nip17MessageService.buildGroupRumor: ONE rumor for
      // the whole fan-out, recipients sorted so the id does not depend on
      // caller argument order (#8188).
      when(
        () => mockMessageService.buildGroupRumor(
          recipientPubkeys: any(named: 'recipientPubkeys'),
          content: any(named: 'content'),
          eventKind: any(named: 'eventKind'),
          additionalTags: any(named: 'additionalTags'),
          createdAt: any(named: 'createdAt'),
        ),
      ).thenAnswer((inv) {
        final recipients =
            (inv.namedArguments[#recipientPubkeys] as List<String>).toList()
              ..sort();
        final content = inv.namedArguments[#content] as String;
        final eventKind =
            (inv.namedArguments[#eventKind] as int?) ??
            EventKind.privateDirectMessage;
        final additionalTags =
            (inv.namedArguments[#additionalTags] as List<List<String>>?) ??
            const <List<String>>[];
        final createdAt = inv.namedArguments[#createdAt] as int?;
        return Event(
          _validPubkeyA,
          eventKind,
          [
            for (final pubkey in recipients) ['p', pubkey],
            ...additionalTags,
          ],
          content,
          createdAt: createdAt,
        );
      });
    });

    DmRepository createRepository({
      String? userPubkey,
      RumorDecryptor? rumorDecryptor,
      Nip04Decryptor? nip04Decryptor,
      DmSyncState? syncState,
      OutgoingDmsDao? outgoingDmsDao,
      PendingGiftWrapsDao? pendingGiftWrapsDao,
      ProcessedGiftWrapsDao? processedGiftWrapsDao,
      RemovedConversationsDao? removedConversationsDao,
      DmReactionsRepository? reactionsRepository,
      NostrSigner? signer,
      DmDecryptIsolateSpawner? decryptIsolateSpawner,
      DmVerifyIsolateSpawner? verifyIsolateSpawner,
      // #4974: inject a stable advertised relay so the publish tests exercise
      // the real path; tests that assert the unconfigured no-op pass null.
      String? dmInboxRelayUrl = 'wss://relay.divine.video',
      List<String> dmInboxDiscoveryRelays = const <String>[],
      List<String> dmInboxLookupRelays = const <String>[],
      List<String> dmInboxTaggedRelays = const <String>[],
      Duration readMarkerDebounceDelay = const Duration(seconds: 3),
      String Function()? sendBatchIdGenerator,
    }) {
      return DmRepository(
        nostrClient: mockNostrClient,
        messageService: mockMessageService,
        directMessagesDao: mockDirectMessagesDao,
        conversationsDao: mockConversationsDao,
        outgoingDmsDao: outgoingDmsDao,
        pendingGiftWrapsDao: pendingGiftWrapsDao,
        processedGiftWrapsDao: processedGiftWrapsDao,
        removedConversationsDao: removedConversationsDao,
        userPubkey: userPubkey ?? _validPubkeyA,
        signer: signer ?? LocalNostrSigner(_validPrivateKey),
        rumorDecryptor: rumorDecryptor,
        nip04Decryptor: nip04Decryptor,
        decryptIsolateSpawner: decryptIsolateSpawner,
        // Default to an inline (no-isolate) verify worker so drain tests never
        // spawn a real verify isolate; it runs the same check inline, so it is
        // behaviour-equivalent. Tests that assert verify routing inject their
        // own recording worker. See #5424.
        verifyIsolateSpawner:
            verifyIsolateSpawner ?? () async => _RecordingVerifyWorker(),
        syncState: syncState,
        reactionsRepository: reactionsRepository,
        dmInboxRelayUrl: dmInboxRelayUrl,
        dmInboxTaggedRelays: dmInboxTaggedRelays,
        dmInboxDiscoveryRelays: dmInboxDiscoveryRelays,
        dmInboxLookupRelays: dmInboxLookupRelays,
        readMarkerDebounceDelay: readMarkerDebounceDelay,
        sendBatchIdGenerator: sendBatchIdGenerator,
        errorReporter: (error, stackTrace, {required site}) {
          reporterCalls.add(_ReporterCall(error, stackTrace, site));
        },
      );
    }

    List<List<String>> additionalTagsFromRumor(
      Event rumorEvent,
      String recipientPubkey,
    ) {
      return rumorEvent.tags
          .where(
            (tag) =>
                !(tag.length >= 2 &&
                    tag[0] == 'p' &&
                    tag[1] == recipientPubkey),
          )
          .map(List<String>.from)
          .toList();
    }

    void stubSendRumor(
      FutureOr<NIP17SendResult> Function(
        Event rumorEvent,
        String recipientPubkey,
      )
      answer,
    ) {
      when(
        () => mockMessageService.sendRumor(
          rumorEvent: any(named: 'rumorEvent'),
          recipientPubkey: any(named: 'recipientPubkey'),
          targetRelays: any(named: 'targetRelays'),
          selfWrapTargetRelays: any(named: 'selfWrapTargetRelays'),
          awaitRecipientOk: any(named: 'awaitRecipientOk'),
          selfWrapOnSoftUnconfirmed: any(named: 'selfWrapOnSoftUnconfirmed'),
        ),
      ).thenAnswer((inv) async {
        final rumorEvent = inv.namedArguments[#rumorEvent] as Event;
        final recipientPubkey = inv.namedArguments[#recipientPubkey] as String;
        return answer(rumorEvent, recipientPubkey);
      });
    }

