      test('skipNip04Fallback: true suppresses NIP-04 publish', () async {
        stubSendRumor(
          (_, recipientPubkey) async => NIP17SendResult.success(
            rumorEventId: _rumorEventId,
            messageEventId: _giftWrapEventId,
            recipientPubkey: recipientPubkey,
