    group('subscription lifecycle', () {
      test('startListening subscribes to kind 1059 events', () async {
        final controller = StreamController<Event>();
        when(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).thenAnswer((_) => controller.stream);
        when(
          () => mockNostrClient.unsubscribe(any()),
        ).thenAnswer((_) async {});

        final repository = createRepository();
        await repository.startListening();

        verify(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).called(1);

        await repository.stopListening();
        await controller.close();
      });

      test('startListening is idempotent', () async {
        final controller = StreamController<Event>();
        when(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).thenAnswer((_) => controller.stream);
        when(
          () => mockNostrClient.unsubscribe(any()),
        ).thenAnswer((_) async {});

        final repository = createRepository();
        await repository.startListening();
        await repository.startListening(); // Second call is no-op

        verify(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).called(1);

        await repository.stopListening();
        await controller.close();
      });

      test('stopListening unsubscribes', () async {
        final controller = StreamController<Event>();
        when(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).thenAnswer((_) => controller.stream);
        when(
          () => mockNostrClient.unsubscribe(any()),
        ).thenAnswer((_) async {});

        final repository = createRepository();
        await repository.startListening();
        await repository.stopListening();

        verify(
          () => mockNostrClient.unsubscribe(any()),
        ).called(1);

        await controller.close();
      });

      test('startListening after stopListening re-subscribes '
          '(inbox can be re-opened)', () async {
        // Return a fresh stream per subscribe call so both listens succeed.
        final controllers = <StreamController<Event>>[];
        when(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).thenAnswer((_) {
          final controller = StreamController<Event>();
          controllers.add(controller);
          return controller.stream;
        });
        when(
          () => mockNostrClient.unsubscribe(any()),
        ).thenAnswer((_) async {});

        final repository = createRepository();

        await repository.startListening();
        await repository.stopListening();
        await repository.startListening();

        // Both opens should have produced a subscribe call on the client.
        verify(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).called(2);

        await repository.stopListening();
        for (final c in controllers) {
          await c.close();
        }
      });

      test('initialize does not open a subscription (lazy inbox)', () async {
        // New behavior: initialize() only wires credentials. The gift-wrap
        // subscription is started by the inbox screen via startListening().
        // This keeps cold start off the UI isolate until the user visits
        // the messages tab. Regression guard for
        // docs/plans/2026-04-05-dm-scaling-fix-design.md.
        final repository =
            DmRepository(
              nostrClient: mockNostrClient,
              messageService: mockMessageService,
              directMessagesDao: mockDirectMessagesDao,
              conversationsDao: mockConversationsDao,
              // Intentionally no userPubkey/signer — initialize() provides them.
            )..setCredentials(
              userPubkey: _validPubkeyA,
              signer: LocalNostrSigner(_validPrivateKey),
              messageService: mockMessageService,
            );

        // The relay client must not have been asked to subscribe.
        verifyNever(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        );
        // But the repository should still be initialized so send() works.
        expect(repository.isInitialized, isTrue);
      });

      test('setCredentials triggers backfillCurrentUserHasSent', () async {
        DmRepository(
          nostrClient: mockNostrClient,
          directMessagesDao: mockDirectMessagesDao,
          conversationsDao: mockConversationsDao,
        ).setCredentials(
          userPubkey: _validPubkeyA,
          signer: LocalNostrSigner(_validPrivateKey),
          messageService: mockMessageService,
        );

        // Let the unawaited _runPostAuthMaintenance() settle.
        await Future<void>.delayed(Duration.zero);

        verify(
          () => mockConversationsDao.backfillCurrentUserHasSent(
            _validPubkeyA,
          ),
        ).called(1);
      });

      test('startListening does not poll the relay', () async {
        // Regression guard: the 10s gift-wrap poll timer was removed
        // because it re-fetched the last 20 events forever on the UI
        // isolate, producing constant dedup skips and log spam. The
        // live subscription is now the sole event source while the
        // inbox is open. See
        // docs/plans/2026-04-05-dm-scaling-fix-design.md.
        final controller = StreamController<Event>();
        when(
          () => mockNostrClient.subscribe(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
          ),
        ).thenAnswer((_) => controller.stream);
        when(
          () => mockNostrClient.unsubscribe(any()),
        ).thenAnswer((_) async {});

        final repository = createRepository();
        await repository.startListening();

        // Wait well beyond any former poll interval.
        await Future<void>.delayed(const Duration(milliseconds: 100));

        // The relay is read EXACTLY once — the one-shot #4974 own kind-10050
        // inbox-relay resolve at subscription open — and never again: no
        // background poller re-fetches events on a timer.
        verify(
          () => mockNostrClient.queryEventsDetailed(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
            useCache: any(named: 'useCache'),
            tempRelays: any(named: 'tempRelays'),
            requireAllRelaysSettled: any(named: 'requireAllRelaysSettled'),
            timeout: any(named: 'timeout'),
          ),
        ).called(1);
        verifyNever(
          () => mockNostrClient.queryEvents(
            any(),
            subscriptionId: any(named: 'subscriptionId'),
            useCache: any(named: 'useCache'),
          ),
        );

        await repository.stopListening();
        await controller.close();
      });

      test(
        'startListening on first ever open uses limit:50 and no since',
        () async {
          final controller = StreamController<Event>();
          when(
            () => mockNostrClient.subscribe(
              any(),
              subscriptionId: any(named: 'subscriptionId'),
            ),
          ).thenAnswer((_) => controller.stream);

          final syncState = _FakeDmSyncState();
          final repository = createRepository(syncState: syncState);
          await repository.startListening();

          final captured =
              verify(
                    () => mockNostrClient.subscribe(
                      captureAny(),
                      subscriptionId: any(named: 'subscriptionId'),
                    ),
                  ).captured.single
                  as List<nostr_filter.Filter>;
          expect(captured, hasLength(1));
          expect(captured.single.limit, 50);
          expect(captured.single.since, isNull);

          await repository.stopListening();
          await controller.close();
        },
      );

      test(
        'startListening on subsequent open uses since = newest - 2d',
        () async {
          const newest = 1700000000;
          final controller = StreamController<Event>();
          when(
            () => mockNostrClient.subscribe(
              any(),
              subscriptionId: any(named: 'subscriptionId'),
            ),
          ).thenAnswer((_) => controller.stream);

          final syncState = _FakeDmSyncState()..newestOverride = newest;
          final repository = createRepository(syncState: syncState);
          await repository.startListening();

          final captured =
              verify(
                    () => mockNostrClient.subscribe(
                      captureAny(),
                      subscriptionId: any(named: 'subscriptionId'),
                    ),
                  ).captured.single
                  as List<nostr_filter.Filter>;
          expect(captured, hasLength(1));
          expect(captured.single.since, newest - 2 * 86400);
          expect(captured.single.limit, isNull);

          await repository.stopListening();
          await controller.close();
        },
      );

      test(
        'startListening derives since from the WIRE boundary, not the rumor '
        'boundary, once one has been recorded (#8209)',
        () async {
          // One NIP-17 message: honest send time in the rumor, outer wrap
          // backdated a day per NIP-17. A relay evaluates `since:` against the
          // outer stamp, so deriving the window from the rumor clock starts it
          // a day above the events it is supposed to admit.
          const rumorNewest = 1700000000;
          const wireNewest = rumorNewest - 86400;
          final controller = StreamController<Event>();
          when(
            () => mockNostrClient.subscribe(
              any(),
              subscriptionId: any(named: 'subscriptionId'),
            ),
          ).thenAnswer((_) => controller.stream);

          final syncState = _FakeDmSyncState()
            ..newestOverride = rumorNewest
            ..newestWireOverride = wireNewest;
          final repository = createRepository(syncState: syncState);
          await repository.startListening();

          final captured =
              verify(
                    () => mockNostrClient.subscribe(
                      captureAny(),
                      subscriptionId: any(named: 'subscriptionId'),
                    ),
                  ).captured.single
                  as List<nostr_filter.Filter>;
          expect(captured.single.since, wireNewest - 2 * 86400);

          await repository.stopListening();
          await controller.close();
        },
      );

      test(
        'since leaves the whole 2-day overlap below the wire boundary, so a '
        'wrap carrying the maximum NIP-17 backdate still matches (#8209)',
        () async {
          // The invariant the window has to hold: our newest processed wrap
          // was stamped at or below the moment it was published, so any wrap
          // published from that moment onward — even one backdated the full
          // two days NIP-17 allows — is at or above `wire - 2d`. Use an old
          // rumor re-wrapped recently (the retry behavior in GiftWrapUtil) to
          // cover the case where the wire boundary narrows the rumor fallback.
          const publishedAt = 1700000000;
          const wireNewest = publishedAt - 3600;
          const rumorNewest = publishedAt - 86400;
          const worstCaseOuter = publishedAt - 2 * 86400;

          expect(wireNewest, greaterThan(rumorNewest));

          final controller = StreamController<Event>();
          when(
            () => mockNostrClient.subscribe(
              any(),
              subscriptionId: any(named: 'subscriptionId'),
            ),
          ).thenAnswer((_) => controller.stream);

          final syncState = _FakeDmSyncState()
            ..newestOverride = rumorNewest
            ..newestWireOverride = wireNewest;
          final repository = createRepository(syncState: syncState);
          await repository.startListening();

          final captured =
              verify(
                    () => mockNostrClient.subscribe(
                      captureAny(),
                      subscriptionId: any(named: 'subscriptionId'),
                    ),
                  ).captured.single
                  as List<nostr_filter.Filter>;
          expect(captured.single.since, wireNewest - 2 * 86400);
          expect(captured.single.since, lessThanOrEqualTo(worstCaseOuter));

          await repository.stopListening();
          await controller.close();
        },
      );

      test(
        'a wrap the relay holds below the window is never served, while a '
        'newer one on the same relay is (#8439)',
        () async {
          // Both wraps sit on the SAME relay and arrive through the SAME REQ.
          // The only thing separating them is which side of `since:` their
          // OUTER stamp falls on, so any handling that reached one would have
          // reached the other. That is what makes the control load-bearing:
          // it rules out "the relay was never read", which is the obvious
          // rival explanation and the one an assertion on the victim alone
          // cannot exclude.
          //
          // Scope: this pins the window and what the relay does with it. The
          // receive pipeline downstream has its own tests, and
          // `recordWireSeen`'s monotonicity is pinned in dm_sync_state_test —
          // together they are what make the loss permanent rather than merely
          // late.
          const wireNewest = 1700000000;
          const since = wireNewest - 2 * 86400;
          // Published earlier than our newest processed wrap and delivered
          // late. #8361's invariant does not reach it: that argument binds
          // only wraps published at or after `wireNewest`, because it needs
          // `outer >= P - 2d` together with `W <= P`.
          const victimOuter = since - 1;
          const controlOuter = wireNewest - 3600;

          Event wrapAt(int createdAt, String id) => Event.fromJson({
            'id': id,
            'pubkey': _validPubkeyC,
            'created_at': createdAt,
            'kind': EventKind.giftWrap,
            'tags': [
              ['p', _validPubkeyA],
            ],
            'content': 'encrypted-content',
            'sig': '',
          });

          final victim = wrapAt(victimOuter, _giftWrapEventId);
          final control = wrapAt(controlOuter, _giftWrapEventId2);
          final relay = _SinceEnforcingRelay([victim, control]);

          when(
            () => mockNostrClient.subscribe(
              any(),
              subscriptionId: any(named: 'subscriptionId'),
            ),
          ).thenAnswer(
            (invocation) => relay.subscribe(
              invocation.positionalArguments.first as List<nostr_filter.Filter>,
            ),
          );
          when(
            () => mockDirectMessagesDao.hasGiftWrap(any()),
          ).thenAnswer((_) async => false);

          final syncState = _FakeDmSyncState()
            ..newestOverride = wireNewest
            ..newestWireOverride = wireNewest;
          final repository = createRepository(
            // Undecryptable on purpose: this test is about which events the
            // relay hands over, not what the pipeline then does with them.
            rumorDecryptor: (_, _) async => null,
            syncState: syncState,
          );

          await repository.startListening();
          await Future<void>.delayed(Duration.zero);

          expect(relay.lastFilters!.single.since, since);
          // The relay answered normally and simply omitted the older wrap —
          // no error, no `CLOSED`, no short page. That silence is why the
          // loss cannot be noticed from the client without a separate probe.
          expect(
            relay.served.map((event) => event.id),
            [control.id],
            reason:
                'the victim wrap is below since:, so the relay never serves '
                'it and nothing downstream can know it exists',
          );

          await repository.stopListening();
          await relay.close();
        },
      );
    });

