          final ledger = _MockProcessedGiftWrapsDao();
          when(
            () => ledger.hasGiftWrap(giftWrap.id),
          ).thenAnswer((_) async => false);
          final recordStarted = Completer<void>();
          final recordGate = Completer<void>();
          when(
            () => ledger.record(
