    group('removeConversation', () {
      // The removal path resolves each conversation before deleting it
      // (#8391), and since #7850 an absent row is skipped entirely rather than
      // deleted-and-tombstoned. These pure-mock tests care about the delete
      // ordering, which only happens for a row that exists — so the lookup
      // echoes back a plain unprotected conversation for whatever id it is
      // asked about. `dm_removal_policy_test.dart` owns the absent-row case.
      setUp(() {
        when(
          () => mockConversationsDao.getConversation(
            any(),
            ownerPubkey: any(named: 'ownerPubkey'),
          ),
        ).thenAnswer(
          (invocation) async => ConversationRow(
            id: invocation.positionalArguments.first as String,
            participantPubkeys: jsonEncode(
              [_validPubkeyA, _validPubkeyB]..sort(),
            ),
            isGroup: false,
            createdAt: 1699999000,
            isRead: true,
            currentUserHasSent: true,
            ownerPubkey: _validPubkeyA,
          ),
        );
      });

      test(
        'deletes messages then conversation in a transaction',
        () async {
          const convId =
              'aabb00112233445566778899aabbccddeeff'
              '0011223344556677889900aabb00';

          when(
            () => mockConversationsDao.runInTransaction<void>(any()),
          ).thenAnswer((inv) async {
            final callback =
                inv.positionalArguments.first as Future<void> Function();
            await callback();
          });
          when(
            () => mockDirectMessagesDao.deleteConversationMessages(
              convId,
              ownerPubkey: any(named: 'ownerPubkey'),
            ),
          ).thenAnswer((_) async => 3);
          when(
            () => mockConversationsDao.deleteConversation(
              convId,
              ownerPubkey: any(named: 'ownerPubkey'),
            ),
          ).thenAnswer((_) async => 1);

          final removedConversationsDao = _MockRemovedConversationsDao();
          final outgoingDmsDao = _MockOutgoingDmsDao();
          when(
            () => removedConversationsDao.record(
              conversationId: convId,
              ownerPubkey: any(named: 'ownerPubkey'),
              removedAt: any(named: 'removedAt'),
            ),
          ).thenAnswer((_) async {});
          when(
            () => outgoingDmsDao.deleteForConversation(
              conversationId: convId,
              ownerPubkey: any(named: 'ownerPubkey'),
            ),
          ).thenAnswer((_) async => 1);

          final repository = createRepository(
            removedConversationsDao: removedConversationsDao,
            outgoingDmsDao: outgoingDmsDao,
          );
          await repository.removeConversation(convId);

          verify(
            () => mockConversationsDao.runInTransaction<void>(any()),
          ).called(1);
          verify(
            () => mockDirectMessagesDao.deleteConversationMessages(
              convId,
              ownerPubkey: any(named: 'ownerPubkey'),
            ),
          ).called(1);
          verify(
            () => mockConversationsDao.deleteConversation(
              convId,
              ownerPubkey: any(named: 'ownerPubkey'),
            ),
          ).called(1);
          verify(
            () => removedConversationsDao.record(
              conversationId: convId,
              ownerPubkey: any(named: 'ownerPubkey'),
              removedAt: any(named: 'removedAt'),
            ),
          ).called(1);
          verify(
            () => outgoingDmsDao.deleteForConversation(
              conversationId: convId,
              ownerPubkey: any(named: 'ownerPubkey'),
            ),
          ).called(1);
        },
      );

      test('rethrows when DAO throws', () async {
        const convId =
            'aabb00112233445566778899aabbccddeeff0011223344556677889900aabb00';

        when(
          () => mockConversationsDao.runInTransaction<void>(any()),
        ).thenAnswer((inv) async {
          final callback =
              inv.positionalArguments.first as Future<void> Function();
          await callback();
        });
        when(
          () => mockDirectMessagesDao.deleteConversationMessages(
            convId,
            ownerPubkey: any(named: 'ownerPubkey'),
          ),
        ).thenThrow(Exception('db error'));

        final repository = createRepository();

        expect(
          () => repository.removeConversation(convId),
          throwsA(isA<Exception>()),
        );
      });
    });

