    group('classifyPotentialRequests', () {
      DmConversation makeConversation({
        required String id,
        required List<String> participantPubkeys,
        bool isGroup = false,
      }) {
        return DmConversation(
          id: id,
          participantPubkeys: participantPubkeys,
          isGroup: isGroup,
          createdAt: 1700000000,
        );
      }

      test('1:1 from followed contact goes to followed list', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyB],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (pk) => pk == _validPubkeyB,
        );

        expect(result.followed, hasLength(1));
        expect(result.requests, isEmpty);
      });

      test('1:1 from unfollowed contact goes to requests list', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyB],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => false,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, hasLength(1));
      });

      test('group with every member followed goes to followed list', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyB, _validPubkeyC],
          isGroup: true,
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => true,
        );

        expect(result.followed, hasLength(1));
        expect(result.requests, isEmpty);
      });

      test('group with any unfollowed member goes to requests', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyB, _validPubkeyC],
          isGroup: true,
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (pk) => pk == _validPubkeyB,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, hasLength(1));
      });

      test('group with no followed members goes to requests', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyB, _validPubkeyC],
          isGroup: true,
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => false,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, hasLength(1));
      });

      test(
        '1:1 with a stale isGroup=true flag still routes a followed peer to '
        'the followed list (#5374)',
        () {
          final conv = makeConversation(
            id: 'conv1',
            participantPubkeys: [_validPubkeyA, _validPubkeyB],
            isGroup: true, // stale/inconsistent flag on a 1:1 row
          );

          final result = DmRepository.classifyPotentialRequests(
            [conv],
            userPubkey: _validPubkeyA,
            isFollowing: (pk) => pk == _validPubkeyB,
          );

          expect(result.followed, hasLength(1));
          expect(result.requests, isEmpty);
        },
      );

      test(
        'conversation with 2+ non-self participants is a request even when '
        'isGroup is false and only one member is followed',
        () {
          final conv = makeConversation(
            id: 'conv1',
            participantPubkeys: [_validPubkeyA, _validPubkeyB, _validPubkeyC],
            // isGroup defaults to false — classification must rely on the
            // participant count, not the flag.
          );

          final result = DmRepository.classifyPotentialRequests(
            [conv],
            userPubkey: _validPubkeyA,
            isFollowing: (pk) => pk == _validPubkeyB,
          );

          expect(result.followed, isEmpty);
          expect(result.requests, hasLength(1));
        },
      );

      test('duplicate peer pubkeys are deduplicated to a 1:1', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyB, _validPubkeyB],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (pk) => pk == _validPubkeyB,
        );

        expect(result.followed, hasLength(1));
        expect(result.requests, isEmpty);
      });

      test('empty input returns both lists empty', () {
        final result = DmRepository.classifyPotentialRequests(
          [],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => false,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, isEmpty);
      });

      // A participant set that collapses to the viewer alone is a
      // self-conversation, which Divine does not support (#8261). It belongs
      // in neither user-facing list: moving the unusable row from Messages to
      // Message requests would only relocate the same broken experience.
      test('self-only participants are hidden from both lists', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => false,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, isEmpty);
      });

      // `[self, self]` is the shape `_cleanupSelfConversations` targets and
      // the one a pre-#2824 self-wrap persisted.
      test('duplicated self participants are hidden from both lists', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA, _validPubkeyA],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => false,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, isEmpty);
      });

      test('mixed-case duplicated self participants are hidden', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [
            _validPubkeyA,
            _validPubkeyA.toUpperCase(),
          ],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (_) => false,
        );

        expect(result.followed, isEmpty);
        expect(result.requests, isEmpty);
      });

      // `validatePubkey` accepts upper-case hex, so the viewer can appear
      // in a stored participant list under a different casing than
      // `userPubkey`. An exact `!=` would leave them in `otherPubkeys` and
      // strand a followed 1:1 peer under Message requests — the #5374
      // failure mode. Matches `_isSelf`, which compares case-insensitively
      // for this reason.
      test('viewer is filtered out regardless of pubkey casing', () {
        final conv = makeConversation(
          id: 'conv1',
          participantPubkeys: [_validPubkeyA.toUpperCase(), _validPubkeyB],
        );

        final result = DmRepository.classifyPotentialRequests(
          [conv],
          userPubkey: _validPubkeyA,
          isFollowing: (pk) => pk == _validPubkeyB,
        );

        expect(result.followed, hasLength(1));
        expect(result.requests, isEmpty);
      });
    });

    group('mergeAndSort', () {
      DmConversation makeConversation({
        required String id,
        int? lastMessageTimestamp,
        int createdAt = 1700000000,
      }) {
        return DmConversation(
          id: id,
          participantPubkeys: const [_validPubkeyA, _validPubkeyB],
          isGroup: false,
          createdAt: createdAt,
          lastMessageTimestamp: lastMessageTimestamp,
        );
      }

      test('returns accepted unchanged when followedPotential is empty', () {
        final accepted = [
          makeConversation(id: 'a', lastMessageTimestamp: 100),
        ];

        final result = DmRepository.mergeAndSort(accepted, []);

        expect(result, same(accepted));
      });

      test('merges and sorts by effectiveTimestamp descending', () {
        final accepted = [
          makeConversation(id: 'a', lastMessageTimestamp: 200),
          makeConversation(id: 'b', lastMessageTimestamp: 100),
        ];
        final followed = [
          makeConversation(id: 'c', lastMessageTimestamp: 150),
        ];

        final result = DmRepository.mergeAndSort(accepted, followed);

        expect(result.map((c) => c.id).toList(), equals(['a', 'c', 'b']));
      });

      test('both empty returns empty', () {
        final result = DmRepository.mergeAndSort([], []);

        expect(result, isEmpty);
      });
    });

    group('extractPinnedSupport', () {
      // The support account and a key it rotated away from. Kept as literals:
      // this package cannot import the app's official-accounts config, and the
      // partition is keyed on whatever the caller injects anyway.
      const support = _validPubkeyB;
      const retired = _validPubkeyC;

      final currentId = DmRepository.computeConversationId([
        _validPubkeyA,
        support,
      ]);
      final retiredId = DmRepository.computeConversationId([
        _validPubkeyA,
        retired,
      ]);

      DmConversation makeConversation({
        required String id,
        required List<String> participantPubkeys,
        bool isGroup = false,
      }) => DmConversation(
        id: id,
        participantPubkeys: participantPubkeys,
        isGroup: isGroup,
        createdAt: 1700000000,
      );

      ({
        DmConversation? pinned,
        String? supportConversationId,
        List<DmConversation> inbox,
        List<DmConversation> requests,
      })
      extract({
        List<DmConversation> inbox = const [],
        List<DmConversation> requests = const [],
        String userPubkey = _validPubkeyA,
        String? supportPubkey = support,
      }) => DmRepository.extractPinnedSupport(
        userPubkey: userPubkey,
        supportPubkey: supportPubkey,
        inbox: inbox,
        requests: requests,
      );

      test('adopts the current-key thread and removes it from the inbox', () {
        final thread = makeConversation(
          id: currentId,
          participantPubkeys: const [_validPubkeyA, support],
        );

        final result = extract(inbox: [thread]);

        expect(result.pinned, equals(thread));
        expect(result.inbox, isEmpty);
        expect(result.supportConversationId, equals(currentId));
      });

      test('adopts an inbound-only thread out of the requests bucket', () {
        final thread = makeConversation(
          id: currentId,
          participantPubkeys: const [_validPubkeyA, support],
        );

        final result = extract(requests: [thread]);

        expect(result.pinned, equals(thread));
        expect(result.requests, isEmpty);
      });

      test('preserves a retired-key thread WITHOUT adopting it', () {
        final thread = makeConversation(
          id: retiredId,
          participantPubkeys: const [_validPubkeyA, retired],
        );

        final result = extract(inbox: [thread]);

        // Nothing remaps the recipient downstream, so returning this as the
        // pin would address replies to a key the account rotated away from.
        expect(result.pinned, isNull);
        expect(result.inbox, equals([thread]));
        expect(result.supportConversationId, equals(currentId));
      });

      test('removes the current-key thread and preserves retired history', () {
        final retiredThread = makeConversation(
          id: retiredId,
          participantPubkeys: const [_validPubkeyA, retired],
        );
        final currentThread = makeConversation(
          id: currentId,
          participantPubkeys: const [_validPubkeyA, support],
        );

        final result = extract(inbox: [retiredThread, currentThread]);

        expect(result.pinned, equals(currentThread));
        expect(result.inbox, equals([retiredThread]));
      });

      test('prefers the inbox copy when the thread is in both buckets', () {
        final accepted = makeConversation(
          id: currentId,
          participantPubkeys: const [_validPubkeyA, support],
        );
        final request = makeConversation(
          id: currentId,
          participantPubkeys: const [_validPubkeyA, support],
          isGroup: true,
        );

        final result = extract(inbox: [accepted], requests: [request]);

        expect(result.pinned, same(accepted));
        expect(result.inbox, isEmpty);
        expect(result.requests, isEmpty);
      });

      test('leaves unrelated conversations untouched', () {
        final other = makeConversation(
          id: 'other',
          participantPubkeys: const [_validPubkeyA, _validPubkeyC],
        );

        final result = extract(inbox: [other]);

        expect(result.inbox, equals([other]));
        expect(result.pinned, isNull);
      });

      test('leaves a group containing the support account in the list', () {
        final group = makeConversation(
          id: 'group',
          participantPubkeys: const [_validPubkeyA, support, _validPubkeyC],
          isGroup: true,
        );

        final result = extract(inbox: [group]);

        // The id hashes ALL sorted participants, so a group can never collide
        // with the 1:1 support thread.
        expect(result.inbox, equals([group]));
        expect(result.pinned, isNull);
      });

      test('is inert when no support pubkey is injected', () {
        final thread = makeConversation(
          id: currentId,
          participantPubkeys: const [_validPubkeyA, support],
        );

        final result = extract(inbox: [thread], supportPubkey: null);

        expect(result.pinned, isNull);
        expect(result.supportConversationId, isNull);
        expect(result.inbox, equals([thread]));
      });

      test('is inert for an empty support pubkey', () {
        final result = extract(supportPubkey: '');

        expect(result.supportConversationId, isNull);
      });

      test('is inert before an identity is known', () {
        final result = extract(userPubkey: '');

        expect(result.supportConversationId, isNull);
      });

      test('is inert when the user IS the support account', () {
        final selfThread = makeConversation(
          id: DmRepository.computeConversationId([support, support]),
          participantPubkeys: const [support, support],
        );

        final result = extract(inbox: [selfThread], userPubkey: support);

        // A self-keyed pin routes with an empty counterparty list, and the
        // maintenance pass deletes self-conversations out from under it.
        expect(result.pinned, isNull);
        expect(result.supportConversationId, isNull);
        expect(result.inbox, equals([selfThread]));
      });
    });

