        'and leaves the row for the retry service',
        () async {
          stubSendRumor(
            (rumorEvent, recipientPubkey) async =>
                const NIP17SendResult.failure('relay unavailable'),
          );

          final repository = createRepository(
            outgoingDmsDao: mockOutgoingDmsDao,
