              blurhash: any(named: 'blurhash'),
              thumbnailUrl: any(named: 'thumbnailUrl'),
              ownerPubkey: any(named: 'ownerPubkey'),
              tagsJson: any(named: 'tagsJson'),
              sendBatchId: any(named: 'sendBatchId'),
