          expect(results.last.queuedRumorId, equals(enqueuedC.id));
          verify(
            () => mockOutgoingDmsDao.markRecipientWrapStatus(
              id: enqueuedC.id,
              status: OutgoingWrapStatus.sent,
              eventId: 'wrap-$_validPubkeyC',
